import re
import csv
import datetime

LOG_DIR = "/app/logs"
TODAY = datetime.date(2025, 8, 12)
LAST_7_START = TODAY - datetime.timedelta(days=6)
LAST_30_START = TODAY - datetime.timedelta(days=29)
MONTH_START = TODAY.replace(day=1)

FILENAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")
SEVERITY_RE = re.compile(r"\[(ERROR|WARNING|INFO)\]")

periods = {
    "today": {"ERROR": 0, "WARNING": 0, "INFO": 0},
    "last_7_days": {"ERROR": 0, "WARNING": 0, "INFO": 0},
    "last_30_days": {"ERROR": 0, "WARNING": 0, "INFO": 0},
    "month_to_date": {"ERROR": 0, "WARNING": 0, "INFO": 0},
    "total": {"ERROR": 0, "WARNING": 0, "INFO": 0},
}

for fname in os.listdir(LOG_DIR):
    m = FILENAME_RE.match(fname)
    if not m:
        continue
    file_date = datetime.date.fromisoformat(m.group(1))
    path = os.path.join(LOG_DIR, fname)
    counts = {"ERROR": 0, "WARNING": 0, "INFO": 0}
    with open(path, "r", errors="replace") as f:
        for line in f:
            sm = SEVERITY_RE.search(line)
            if sm:
                counts[sm.group(1)] += 1

    for sev, c in counts.items():
        periods["total"][sev] += c
        if file_date == TODAY:
            periods["today"][sev] += c
        if LAST_7_START <= file_date <= TODAY:
            periods["last_7_days"][sev] += c
        if LAST_30_START <= file_date <= TODAY:
            periods["last_30_days"][sev] += c
        if MONTH_START <= file_date <= TODAY:
            periods["month_to_date"][sev] += c

with open("/app/summary.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["period", "severity", "count"])
    for period in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for sev in ["ERROR", "WARNING", "INFO"]:
            writer.writerow([period, sev, periods[period][sev]])

print("done")
